def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_prev = max(dangerous_prev) if dangerous_prev else highest_prev

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, pressure_prev + 2.0)
    elif no_water_days >= 1:
        bid = max(DAILY_SALARY * 0.82, pressure_prev + 1.5)
    elif hp <= 4:
        bid = max(DAILY_SALARY * 0.72, pressure_prev + 1.0 if tight_supply else DAILY_SALARY * 0.62)
    else:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.68, highest_prev + 1.2)
        elif medium_supply:
            if highest_prev >= DAILY_SALARY * 0.9:
                bid = DAILY_SALARY * 0.52
            else:
                bid = max(DAILY_SALARY * 0.5, highest_prev * 0.92)
        else:
            if highest_prev >= DAILY_SALARY * 0.9:
                bid = DAILY_SALARY * 0.35
            else:
                bid = DAILY_SALARY * 0.42

    reserve = 0.0
    if day <= 3:
        reserve = DAILY_SALARY * 1.2
    elif day <= 7:
        reserve = DAILY_SALARY * 0.7
    else:
        reserve = DAILY_SALARY * 0.3

    if hp <= 3 or no_water_days >= 1:
        reserve = 0.0

    affordable = max(0.0, budget - reserve)
    if affordable <= 0:
        affordable = min(budget, DAILY_SALARY * 0.55)

    bid = min(bid, affordable)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))
